// h264/ring_words_sys.sv -- the HPS interface's status words whose sources are on clk_sys (generated by tools/ring_layout.py -- edit the tables there, never this file).
// A mux on the word index: combinational, the index quasi-static (h264/ring_stat.sv holds
// it through the snapshot). Words of other domains read 0 here.

`default_nettype none

module ring_words_sys (
    input  wire  [6:0]  ix,
    input  wire  [31:0] f_seq_head,          // w3: the status sequence: +1 a frame (the heartbeat); read LAST
    input  wire  [7:0] f_state,             // w4: STATE_*
    input  wire  [7:0] f_err,               // w4: ERR_* (the session's first)
    input  wire  [7:0] f_live,              // w4: LIVE_* bits
    input  wire  [7:0] f_osd,               // w4: the OSD settings: status[4:1] (aspect, deinterlace)
    input  wire  [31:0] f_err_pos,           // w4: the offending record's index, or the offending write index
    input  wire  [63:0] f_err_word,          // w6: the offending header word 0 verbatim (0 for an index error)
    input  wire  [32:0] f_stc,               // w7: the presentation clock (90 kHz)
    input  wire  [15:0] f_lag_ms,            // w7: the last pickup's lag, ms (signed)
    input  wire  [31:0] f_n_au,              // w8: VIDEO_AU records consumed
    input  wire  [31:0] f_n_audio,           // w8: AUDIO records queued for playing (0.4: skipped)
    input  wire  [31:0] f_n_pad,             // w9: PAD records
    input  wire  [31:0] f_n_streams,         // w9: streams started (session starts + DISCONTINUITY)
    input  wire  [31:0] f_es_bytes,          // w10: payload bytes delivered to the decoder
    input  wire  [31:0] f_ll_mismatch,       // w10: VIDEO_AUs whose LOW_LATENCY differs from the stream's first
    input  wire  [31:0] f_disp_dc,           // w25: decided (store, parity) changes (the judder pair's first half)
    input  wire  [31:0] f_disp_pick,         // w25: pickups
    input  wire  [31:0] f_disp_skip,         // w26: pictures skipped in low latency
    input  wire  [15:0] f_disp_late,         // w26: late pickups
    input  wire  [15:0] f_disp_starve,       // w26: starved refreshes
    input  wire  [15:0] f_disp_cadence,      // w27: cadence errors
    input  wire  [7:0] f_disp_reanchor,     // w27: re-anchors
    input  wire  [2:0] f_disp_flags,        // w27: disp_ctl flags (timing defaulted / clamped / pic_struct)
    input  wire  [3:0] f_disp_lone,         // w27: (0.7) lone PTS disbelieved: a tag off the timeline by more than half a refresh and at most 0.5 s, the tag before it believed -- taken as untagged (saturating)
    input  wire  [1:0] f_osd_aspect,        // w27: (0.4) the OSD: Aspect Ratio -- 0 Auto, 1 4:3, 2 16:9
    input  wire  [1:0] f_osd_deint,         // w27: (0.4) Deinterlace -- 0 Weave, 1 Bob, 2 Blend
    input  wire  [1:0] f_osd_video_out,     // w27: (0.4) Video Output -- 0 Auto, 1 Interlaced, 2 Progressive, 3 Native (HDMI) (0.10)
    input  wire  [0:0] f_osd_hdmi_deint,    // w27: (0.4) HDMI Deinterlace -- 0 Weave, 1 Bob
    input  wire  [1:0] f_osd_analog_aspect, // w27: (0.4) Analog Aspect -- 0 Auto, 1 Fit, 2 Letterbox, 3 Crop
    input  wire  [1:0] f_osd_refresh,       // w27: (0.4) Refresh Rate -- 0 Auto, 1 59.94 Hz, 2 60 Hz, 3 50 Hz
    input  wire  [1:0] f_osd_anti_twitter,  // w27: (0.4) Anti-Twitter -- 0 Auto (the stream's GRAPHICS), 1 Off, 2 On
    input  wire  [2:0] f_set_err,           // w27: (0.4) the last settings request's result: 0 applied, 1 a value out of range, 2 a reserved bit set, 3 an empty mask
    input  wire  [15:0] f_gfx_mismatch,      // w27: (0.4) VIDEO_AUs whose GRAPHICS differs from the stream's first (saturating)
    input  wire  [15:0] f_disp_fetch_late,   // w30: disp_reader: lines begun before their rows were all fetched (past the fit's caps; saturating)
    input  wire  [0:0] f_fit_crop_bad,      // w30: the shown picture's crop left nothing: ignored, the coded picture shown whole (0.17: 0 while fit_valid is 0)
    input  wire  [0:0] f_fit_clamp,         // w30: the fitted rectangle clamped at 8,191 (an absurd SAR under Crop) (0.17: 0 while fit_valid is 0)
    input  wire  [0:0] f_fit_snap,          // w30: the shown picture is within 3.5 % of the raster: shown 1:1, unscaled (0.17: 0 while fit_valid is 0)
    input  wire  [1:0] f_raster_std,        // w30: (0.3) the raster's rate: 0 59.94 Hz, 1 60.00 Hz (525 lines, 480 active), 2 50 Hz (625, 576 active); 3 reserved
    input  wire  [0:0] f_raster_il,         // w30: (0.3) the raster is interlaced (480i / 576i: a refresh is a field)
    input  wire  [0:0] f_raster_auto,       // w30: (0.3) Refresh Rate is Auto: the rate follows the stream's VUI rate (latched at its first picture)
    input  wire  [0:0] f_anti_twitter,      // w30: (0.3) anti-twitter is applied to the shown picture
    input  wire  [7:0] f_set_seq,           // w30: (0.4) the sequence number of the last settings request consumed (applied or refused)
    input  wire  [12:0] f_fit_ow,            // w30: the shown picture's rectangle on the raster (720 x 480 or 576): width (pixels) (0.17: 0 while fit_valid is 0)
    input  wire  [0:0] f_fit_valid,         // w30: (0.17) a picture is shown: the fit's fields (here) and its place on the raster (word 80's pic_x0 / pic_y0) describe it; 0: nothing is shown and they read 0 (a 0.16 core reads 0 here, its fit fields as before)
    input  wire  [12:0] f_fit_oh,            // w30: ... height (frame lines)
    input  wire  [31:0] f_seq_tail,          // w31: the status sequence again: read FIRST (equal to seq_head = a consistent copy)
    input  wire  [7:0] f_geometry_ack_seq,  // w31: (1.2) calibrated picture rectangle request sequence consumed; 0 before a request
    input  wire  [1:0] f_geometry_error,    // w31: (1.2) 0 applied, 1 range error, 2 reserved bits set; 3 reserved
    input  wire  [1:0] f_aud_state,         // w40: (0.5) audio: 0 idle (nothing queued), 1 armed (queued, waiting to start), 2 playing
    input  wire  [0:0] f_aud_ll,            // w40: (0.5) audio follows the low-latency rule (the stream's LOW_LATENCY), else paced by the STC
    input  wire  [8:0] f_aud_q_rec,         // w40: (0.5) AUDIO records queued, not yet played (at most AUD_MAX_RECORDS)
    input  wire  [31:0] f_aud_q_samples,     // w40: (0.5) stereo samples queued, not yet played
    input  wire  [31:0] f_aud_played,        // w41: (0.5) samples played (counted at the gate, silence not included)
    input  wire  [31:0] f_aud_records,       // w41: (0.5) AUDIO records finished (played, dropped or cut by a reset)
    input  wire  [31:0] f_aud_gap,           // w42: (0.5) samples of silence played for an early record (paced: a gap in the audio)
    input  wire  [31:0] f_aud_late,          // w42: (0.5) samples dropped: late (paced), or a burst past the low-latency maximum
    input  wire  [15:0] f_aud_underruns,     // w43: (0.5) the queue ran empty while playing (saturating)
    input  wire  [15:0] f_aud_slip_drop,     // w43: (0.5) low latency: single samples dropped for drift (saturating)
    input  wire  [15:0] f_aud_slip_rep,      // w43: (0.5) low latency: single samples repeated for drift (saturating)
    input  wire  [15:0] f_aud_anchor,        // w43: (0.5) the audio started the STC (no picture had; saturating)
    input  wire  [31:0] f_aud_offset,        // w44: (0.5) STC minus PTS at the last tagged record's first sample, 90 kHz ticks (signed; paced)
    input  wire  [31:0] f_aud_hold_bytes,    // w44: (0.5) ring bytes the queued audio holds behind the reader
    input  wire  [0:0] f_paused,            // w45: (0.5) the pause is applied (word 34's PAUSE, during a session)
    input  wire  [0:0] f_ctl_err,           // w45: (0.5) the last word 34 read had a reserved bit set: refused, the previous values kept
    input  wire  [7:0] f_atten,             // w45: (0.5) the attenuation applied (word 34's ATTEN)
    input  wire  [31:0] f_ovl_gen,           // w46: (0.9) the overlay: the generation of the last consistent descriptor read
    input  wire  [1:0] f_ovl_state,         // w46: (0.9) 0 off, 1 accepted (shown while a session is open), 2 refused
    input  wire  [0:0] f_ovl_at,            // w46: (0.9) the overlay is anti-twittered (480i / 576i, Anti-Twitter Auto or On)
    input  wire  [0:0] f_ovl_clip,          // w46: (0.9) the canvas is taller (0.10: or wider) than the raster: its edge lines (columns) are not shown
    input  wire  [3:0] f_ovl_err,           // w46: (0.9) OVL_E_*: the first check a refused descriptor failed (0 unless refused)
    input  wire  [7:0] f_ovl_torn,          // w46: (0.9) descriptors read torn (gen_lo != gen_hi): ignored (saturating)
    input  wire  [15:0] f_ovl_late,          // w46: (0.9) raster lines whose overlay line was not fetched in time: shown transparent (saturating)
    input  wire  [11:0] f_ar_x,              // w47: (0.9) the aspect HDMI's scaler is given (VIDEO_ARX): the raster (0.10: word 80's raster_w x raster_h) is shown ar_x : ar_y wide
    input  wire  [11:0] f_ar_y,              // w47: (0.9) ... VIDEO_ARY
    input  wire  [31:0] f_ovl_lines,         // w47: (0.9) canvas lines the overlay fetched (free-running: liveness)
    input  wire  [11:0] f_raster_w,          // w80: (0.10) the raster's active width, pixels (the overlay's canvas and the picture are placed on it)
    input  wire  [11:0] f_raster_h,          // w80: (0.10) ... its active height, frame lines (480 / 576; a field is half of them)
    input  wire  [1:0] f_raster_mode,       // w80: (0.10) 0 fitted (720 wide), 1 native, 2 native but this picture fell back to fitted
    input  wire  [0:0] f_raster_lb,         // w80: (0.10) the picture is letterboxed inside the raster so the raster is shown at the HDMI display's shape (A')
    input  wire  [1:0] f_video_out,         // w80: (0.14) Video Output as the core resolved it: 1 Interlaced, 2 Progressive, 3 Native (HDMI) -- Auto is one of them (a 0.13 core reads 0)
    input  wire  [2:0] f_colour,            // w80: (0.16) the shown picture's colour code (COLOUR_*: 1-6; 1 before any picture; a 0.15 core reads 0)
    input  wire  [12:0] f_pic_x0,            // w80: (0.10) the shown picture's rectangle (word 30's fit_ow x fit_oh) on the raster: left, two's complement (negative under Crop); (0.17) 0 while word 30's fit_valid is 0
    input  wire  [12:0] f_pic_y0,            // w80: (0.10) ... top, frame lines, two's complement
    input  wire  [15:0] f_rum_p0,            // w82: (0.13) pad 0's rumble passed to Main now ({large, small}; 0 outside a session)
    input  wire  [15:0] f_rum_p1,            // w82: (0.13) pad 1's
    input  wire  [15:0] f_rum_p2,            // w82: (0.13) pad 2's
    input  wire  [15:0] f_rum_p3,            // w82: (0.13) pad 3's
    input  wire  [15:0] f_rum_p4,            // w83: (0.13) pad 4's
    input  wire  [15:0] f_rum_p5,            // w83: (0.13) pad 5's
    input  wire  [31:0] f_rum_changes,       // w83: (0.13) the rumble passed to Main changed (any pad), counted since the PLL lock (wrapping)
    input  wire  [19:0] f_pic_held,          // w84: (0.15) the stores the display holds (queued or shown): set at an emission, cleared at the release
    input  wire  [0:0] f_pic_mode,          // w84: (0.15) the current stream is a picture stream (its first video record was a PICTURE)
    input  wire  [31:0] f_pic_emitted,       // w84: (0.15) PICTURE records emitted to the display since the PLL lock (wrapping): with pic_held, the store rule
    input  wire  [31:0] f_disp_fhold,        // w85: (0.15) 480i / 576i: field pairs held one refresh so that each starts on the raster field of its first field (reset per stream, as disp_late)
    input  wire  [7:0] f_vui_matrix,        // w86: (0.16) the shown picture's SPS matrix_coefficients as coded (2 when absent; a program's picture 2)
    input  wire  [7:0] f_vui_primaries,     // w86: (0.16) ... colour_primaries (2 when absent)
    input  wire  [7:0] f_vui_transfer,      // w86: (0.16) ... transfer_characteristics (2 when absent)
    input  wire  [0:0] f_vui_full_range,    // w86: (0.16) ... video_full_range_flag (0 when absent)
    input  wire  [0:0] f_vui_colour_present, // w86: (0.16) ... colour_description_present_flag
    input  wire  [0:0] f_colour_override,   // w86: (0.16) the stream's first VIDEO_AU set a non-zero colour (it overrides the stream's tags)
    input  wire  [15:0] f_colour_unsup,      // w86: (0.16) pictures shown by the size rule because their matrix is not supported (0 GBR, 8 YCgCo, 10 BT.2020 cl, 11+), since the stream began (saturating)
    input  wire  [15:0] f_colour_mismatch,   // w86: (0.16) VIDEO_AUs whose colour differed from the stream's first, since the stream began (saturating)
    input  wire  [2:0] f_display_profile,   // w87: (1.3) OSD selection: 0 480i60, 1 480p60, 2 576i50, 3 576p50, 4 Native HDMI
    input  wire  [0:0] f_display_match_refresh, // w87: (1.3) Match Video Refresh is enabled; its playback-only rate override restores the OSD profile when idle
    input  wire  [0:0] f_display_240p,      // w87: (1.3) 240p Playback is requested; 288p at 50 Hz
    input  wire  [0:0] f_display_film_speed, // w87: (1.3) Film Speed is enabled for the program's frame-rate choice
    input  wire  [0:0] f_display_wide,      // w87: (1.3) Display Shape is set to 16:9 (0 when 4:3)
    input  wire  [3:0] f_display_effective_profile, // w87: (1.3) resolved output family: 0 480i, 1 480p, 2 576i, 3 576p, 4 Native HDMI
    input  wire  [1:0] f_display_raster_std, // w87: (1.3) resolved raster rate: 0 59.94, 1 60.00, 2 50; 3 reserved
    input  wire  [0:0] f_display_interlaced, // w87: (1.3) resolved output is interlaced
    input  wire  [0:0] f_display_deflicker, // w87: (1.3) global vertical De-flicker is active; only applies to interlaced output
    input  wire  [0:0] f_display_240p_active, // w87: (1.3) the physical raster is currently progressive 240p or 288p
    input  wire  [1:0] f_display_refresh_match_mode, // w87: (1.4) Refresh Rate Match: 0 Off, 1 50/60; upper encodings reserved
    output logic [63:0] w
);
    always_comb begin
        w = 64'd0;
        case (ix)
            7'd0: begin w[63:0] = 64'h343632485453694D; end
            7'd1: begin w[15:0] = 16'h104; w[31:16] = 16'h20; w[47:32] = 16'h20; w[63:48] = 16'h28; end
            7'd2: begin w[31:0] = 32'h31800000; w[63:32] = 32'h800000; end
            7'd3: begin w[31:0] = f_seq_head; w[63:32] = 32'h400000; end
            7'd4: begin w[7:0] = f_state; w[15:8] = f_err; w[23:16] = f_live; w[31:24] = f_osd; w[63:32] = f_err_pos; end
            7'd6: begin w[63:0] = f_err_word; end
            7'd7: begin w[32:0] = f_stc; w[63:48] = f_lag_ms; end
            7'd8: begin w[31:0] = f_n_au; w[63:32] = f_n_audio; end
            7'd9: begin w[31:0] = f_n_pad; w[63:32] = f_n_streams; end
            7'd10: begin w[31:0] = f_es_bytes; w[63:32] = f_ll_mismatch; end
            7'd25: begin w[31:0] = f_disp_dc; w[63:32] = f_disp_pick; end
            7'd26: begin w[31:0] = f_disp_skip; w[47:32] = f_disp_late; w[63:48] = f_disp_starve; end
            7'd27: begin w[15:0] = f_disp_cadence; w[23:16] = f_disp_reanchor; w[26:24] = f_disp_flags; w[30:27] = f_disp_lone; w[33:32] = f_osd_aspect; w[35:34] = f_osd_deint; w[37:36] = f_osd_video_out; w[38:38] = f_osd_hdmi_deint; w[40:39] = f_osd_analog_aspect; w[42:41] = f_osd_refresh; w[44:43] = f_osd_anti_twitter; w[47:45] = f_set_err; w[63:48] = f_gfx_mismatch; end
            7'd30: begin w[15:0] = f_disp_fetch_late; w[16:16] = f_fit_crop_bad; w[17:17] = f_fit_clamp; w[18:18] = f_fit_snap; w[20:19] = f_raster_std; w[21:21] = f_raster_il; w[22:22] = f_raster_auto; w[23:23] = f_anti_twitter; w[31:24] = f_set_seq; w[44:32] = f_fit_ow; w[45:45] = f_fit_valid; w[60:48] = f_fit_oh; end
            7'd31: begin w[31:0] = f_seq_tail; w[39:32] = f_geometry_ack_seq; w[41:40] = f_geometry_error; end
            7'd40: begin w[1:0] = f_aud_state; w[2:2] = f_aud_ll; w[24:16] = f_aud_q_rec; w[63:32] = f_aud_q_samples; end
            7'd41: begin w[31:0] = f_aud_played; w[63:32] = f_aud_records; end
            7'd42: begin w[31:0] = f_aud_gap; w[63:32] = f_aud_late; end
            7'd43: begin w[15:0] = f_aud_underruns; w[31:16] = f_aud_slip_drop; w[47:32] = f_aud_slip_rep; w[63:48] = f_aud_anchor; end
            7'd44: begin w[31:0] = f_aud_offset; w[63:32] = f_aud_hold_bytes; end
            7'd45: begin w[0:0] = f_paused; w[1:1] = f_ctl_err; w[15:8] = f_atten; end
            7'd46: begin w[31:0] = f_ovl_gen; w[33:32] = f_ovl_state; w[34:34] = f_ovl_at; w[35:35] = f_ovl_clip; w[39:36] = f_ovl_err; w[47:40] = f_ovl_torn; w[63:48] = f_ovl_late; end
            7'd47: begin w[11:0] = f_ar_x; w[23:12] = f_ar_y; w[63:32] = f_ovl_lines; end
            7'd80: begin w[11:0] = f_raster_w; w[23:12] = f_raster_h; w[25:24] = f_raster_mode; w[26:26] = f_raster_lb; w[28:27] = f_video_out; w[31:29] = f_colour; w[44:32] = f_pic_x0; w[60:48] = f_pic_y0; end
            7'd81: begin w[15:0] = 16'hE10; w[27:16] = 12'h2D0; w[63:32] = 32'h1A5E0; end
            7'd82: begin w[15:0] = f_rum_p0; w[31:16] = f_rum_p1; w[47:32] = f_rum_p2; w[63:48] = f_rum_p3; end
            7'd83: begin w[15:0] = f_rum_p4; w[31:16] = f_rum_p5; w[63:32] = f_rum_changes; end
            7'd84: begin w[19:0] = f_pic_held; w[20:20] = f_pic_mode; w[31:24] = 8'h14; w[63:32] = f_pic_emitted; end
            7'd85: begin w[31:0] = f_disp_fhold; end
            7'd86: begin w[7:0] = f_vui_matrix; w[15:8] = f_vui_primaries; w[23:16] = f_vui_transfer; w[24:24] = f_vui_full_range; w[25:25] = f_vui_colour_present; w[26:26] = f_colour_override; w[47:32] = f_colour_unsup; w[63:48] = f_colour_mismatch; end
            7'd87: begin w[2:0] = f_display_profile; w[3:3] = f_display_match_refresh; w[4:4] = f_display_240p; w[5:5] = f_display_film_speed; w[6:6] = f_display_wide; w[10:7] = f_display_effective_profile; w[12:11] = f_display_raster_std; w[13:13] = f_display_interlaced; w[14:14] = f_display_deflicker; w[15:15] = f_display_240p_active; w[17:16] = f_display_refresh_match_mode; end
            default: ;
        endcase
    end
endmodule

`default_nettype wire
